// Challenge: Import 50k product records from CSV without freezing the app
@Service
public class ProductImportService {
    private final ProductRepository repository;
    private static final int BATCH_SIZE = 500;

    public ImportResult importProducts(InputStream csvStream) {
        var reader = new BufferedReader(new InputStreamReader(csvStream));
        var batch = new ArrayList<Product>(BATCH_SIZE);
        int processedCount = 0;

        String line;
        while ((line = reader.readLine()) != null) {
            var product = parseProduct(line);
            batch.add(product);

            if (batch.size() == BATCH_SIZE) {
                repository.saveAll(batch);  // Batch insert reduces DB calls
                processedCount += batch.size();
                batch.clear();  // Prevent memory buildup
            }
        }

        if (!batch.isEmpty()) {
            repository.saveAll(batch);  // Save remaining records
            processedCount += batch.size();
        }

        return new ImportResult(processedCount, Duration.ofMillis(System.currentTimeMillis()));
    }
}

