@Service
public class BookingService {
    public Booking createBooking(BookingRequest request) {
        validateBookingRequest(request);  // My contribution: validation logic

        var user = userService.findById(request.getUserId());
        var room = roomService.findAvailableRoom(request.getRoomType());

        if (room.isEmpty()) {
            throw new RoomUnavailableException("No rooms available");
        }

        var booking = new Booking(
            user.orElseThrow(),
            room.get(),
            request.getCheckIn(),
            request.getCheckOut()
        );

        return bookingRepository.save(booking);
    }

    private void validateBookingRequest(BookingRequest request) {
        // Teammate suggested adding date range validation after code review
        if (request.getCheckOut().isBefore(request.getCheckIn())) {
            throw new IllegalArgumentException("Check-out must be after check-in");
        }
    }
}

