// IMPROVED: Authentication and proper error responses
@RestController
public class AccountController {
    private final AccountService accountService;

    @GetMapping("/accounts/{id}")
    public ResponseEntity<AccountDTO> getAccount(
        @PathVariable Long id,
        @AuthenticationPrincipal User currentUser  // Spring Security injects authenticated user
    ) {
        // Authorization check: users can only see their own account
        if (!accountService.canUserAccessAccount(currentUser.getId(), id)) {
            return ResponseEntity.status(HttpStatus.FORBIDDEN)
                .body(null);  // Or return error DTO with message
        }

        return accountService.findById(id)
            .map(account -> ResponseEntity.ok(account))
            .orElse(ResponseEntity.notFound().build());  // Proper 404 instead of exception
    }
}

// Global exception handler for consistent error responses
@RestControllerAdvice
public class GlobalExceptionHandler {
    @ExceptionHandler(AccessDeniedException.class)
    public ResponseEntity<ErrorResponse> handleAccessDenied(AccessDeniedException ex) {
        var error = new ErrorResponse("FORBIDDEN", "You don't have permission to access this resource");
        return ResponseEntity.status(HttpStatus.FORBIDDEN).body(error);
    }
}

// User entity: One user has many orders
@Entity
@Table(name = "users")
public class User {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String email;
    private String name;

    @OneToMany(mappedBy = "user", cascade = CascadeType.ALL)
    private List<Order> orders = new ArrayList<>();  // One-to-many relationship
}

// Order entity: Each order belongs to one user, has many items
@Entity
@Table(name = "orders")
public class Order {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne
    @JoinColumn(name = "user_id")  // Foreign key, should be indexed
    private User user;

    @OneToMany(mappedBy = "order", cascade = CascadeType.ALL)
    private List<OrderItem> items = new ArrayList<>();

    private BigDecimal totalAmount;
}

// OrderItem entity: Join table for many-to-many between orders and products
@Entity
@Table(name = "order_items")
public class OrderItem {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne
    @JoinColumn(name = "order_id")
    private Order order;

    @ManyToOne
    @JoinColumn(name = "product_id")
    private Product product;

    private Integer quantity;
}
